local key = datos[1]

local function bxor(a, b)
    local resultado = 0
    local potencia = 1
    while a > 0 or b > 0 do
        local bitA = a % 2
        local bitB = b % 2
        if bitA ~= bitB then
            resultado = resultado + potencia
        end
        a = math.floor(a / 2)
        b = math.floor(b / 2)
        potencia = potencia * 2
    end
    return resultado
end

