for i = 1, total do
    local keyByte = string.byte(key, ((i - 1) % keyLen) + 1)
    local mask = (i * 73 + keyLen * 29 + 17) % 256
    local decodedByte = bxor(bxor(encrypted[i], keyByte), mask)
    output[total - i + 1] = string.char(decodedByte)
end

local source = table.concat(output)
local marker = "--[[NEXUS_EDGE_RELEASE_OK]]\n"

